const fs = require('fs');
const orders = JSON.parse(fs.readFileSync('__ORDERS_PATH__', 'utf8'));
const item = $input.first().json;
const body = item.body || item;
const text = String(body.ticket || body.text || JSON.stringify(body));
const match = text.toUpperCase().match(/DF-\d+/);
const id = match ? match[0] : '';
const row = orders[id];
const order = row ? Object.assign({ found: true, order_id: id }, row) : { found: false, order_id: id, reason: 'unknown order' };
return [{ json: { ticket: text, ticket_id: body.ticket_id || '', order: order } }];

const raw = $input.first().json;
const msg = (raw.message && raw.message.content) || raw.response || JSON.stringify(raw);
const lookup = $('Lookup order').first().json;
return [{ json: { skipped: false, ticket_id: lookup.ticket_id || '', order: lookup.order, reply: String(msg) } }];
